    def count_odd_digit_numbers_up_to_digit_length(digit_length: int) -> int:
        # If digit length is even, the odd digit numbers are from 10^(digit_length-1) to 10^digit_length - 1
        if digit_length % 2 == 0:
            return 0
        # If digit length is odd, the odd digit numbers are from 10^(digit_length-1) to 10^digit_length - 1
        else:
            return 9 * 10 ** ((digit_length - 1) // 2)

    count = 0
    length = 1

    while True:
        # Calculate numbers with current length
        numbers_with_current_length = min(10 ** length - 1, n) - 10 ** (length - 1) + 1
        if numbers_with_current_length <= 0:
            break
        if length % 2 != 0:
            count += numbers_with_current_length
        length += 1

    return count

